package com.coffeeshop.service;import com.coffeeshop.dto.ExpenseCommands;import com.coffeeshop.model.ExpenseModels;import com.coffeeshop.repository.ExpenseRepository;import java.math.*;import java.util.*;public final class ExpenseService{private final ExpenseRepository repository;public ExpenseService(ExpenseRepository r){repository=Objects.requireNonNull(r);}public ExpenseModels.Catalog catalog(){return repository.load();}public long saveCategory(ExpenseCommands.Category q){Objects.requireNonNull(q);if(q.id()!=null&&empty(q.version()))throw new IllegalArgumentException("Refresh this category and try again.");return repository.saveCategory(new ExpenseCommands.Category(q.id(),required(q.code(),50,"Category code"),required(q.name(),150,"Category name"),q.active(),q.version()));}public void setCategoryActive(ExpenseModels.Category c,boolean active){Objects.requireNonNull(c);repository.setCategoryActive(c.id(),active,c.version());}public long saveExpense(ExpenseCommands.Expense q,long user){Objects.requireNonNull(q);if(q.categoryId()<=0)throw new IllegalArgumentException("Select an expense category.");if(q.expensedAt()==null)throw new IllegalArgumentException("Expense date is required.");if(q.amount()==null||q.amount().signum()<=0)throw new IllegalArgumentException("Amount must be greater than zero.");if(user<=0)throw new IllegalArgumentException("An authenticated user is required.");if(q.id()!=null&&empty(q.version()))throw new IllegalArgumentException("Refresh this expense and try again.");return repository.saveExpense(new ExpenseCommands.Expense(q.id(),q.categoryId(),q.expensedAt(),q.amount().setScale(4,RoundingMode.HALF_UP),optional(q.description(),500,"Description"),optional(q.reference(),100,"Reference"),optional(q.notes(),1000,"Notes"),q.version()),user);}private static boolean empty(byte[]v){return v==null||v.length==0;}private static String required(String v,int m,String n){if(v==null||v.isBlank())throw new IllegalArgumentException(n+" is required.");String x=v.trim();if(x.length()>m)throw new IllegalArgumentException(n+" is too long.");return x;}private static String optional(String v,int m,String n){return v==null||v.isBlank()?null:required(v,m,n);}}
